snippet_er.code:
erDiagram
    %% 資料表名稱用英文大寫，欄位：型別 名稱 PK或FK "說明"
    %% 關聯：||--o{ 一對多、||--|| 一對一、}o--o{ 多對多
    TABLE_A ||--o{ TABLE_B : "關聯說明"
    TABLE_A {
        string a_id PK "編號"
        string name "名稱"
    }
    TABLE_B {
        string b_id PK "編號"
        string a_id FK "TABLE_A 的編號"
        date created_at "建立日期"
    }

snippet_class.code:
classDiagram
    %% 類別、屬性、方法用英文，中文寫在關聯的冒號後面
    %% 關聯：--> 關聯、*-- 組合、o-- 聚合、<|-- 繼承
    class ClassA {
        +String id
        +String name
        +doSomething()
    }
    class ClassB {
        +String id
    }
    ClassA "1" --> "*" ClassB : 關聯說明
